```architecture
{
  "ok": true,
  "diagram": {
    "version": 1,
    "title": "Outbox Pattern for Atomic Updates and Event Publishing",
    "description": "The Outbox Pattern ensures atomicity when updating databases and publishing events in a microservices architecture",
    "view": "data-flow",
    "pattern": "microservices",
    "direction": "LR",
    "groups": [
      {
        "id": "services",
        "label": "Microservices Layer",
        "tone": "blue"
      },
      {
        "id": "messaging",
        "label": "Message Broker",
        "tone": "purple"
      },
      {
        "id": "storage",
        "label": "Database Storage",
        "tone": "amber"
      },
      {
        "id": "event-handlers",
        "label": "Event Handlers",
        "tone": "slate"
      }
    ],
    "nodes": [
      {
        "id": "order-service",
        "component": "service",
        "label": "Order Service",
        "group": "services"
      },
      {
        "id": "outbox-table",
        "component": "database",
        "label": "Outbox Table",
        "group": "storage"
      },
      {
        "id": "message-broker",
        "component": "apache-kafka",
        "label": "Message Broker",
        "group": "messaging"
      },
      {
        "id": "event-handler",
        "component": "service",
        "label": "Event Handler",
        "group": "event-handlers"
      },
      {
        "id": "database",
        "component": "postgres",
        "label": "Primary Database",
        "group": "storage"
      }
    ],
    "edges": [
      {
        "from": "order-service",
        "to": "outbox-table",
        "kind": "write",
        "label": "Save to Outbox"
      },
      {
        "from": "order-service",
        "to": "database",
        "kind": "write",
        "label": "Update Database"
      },
      {
        "from": "outbox-table",
        "to": "message-broker",
        "kind": "publish",
        "label": "Publish Event"
      },
      {
        "from": "message-broker",
        "to": "event-handler",
        "kind": "trigger",
        "label": "Trigger Event Handler"
      }
    ],
    "legend": [
      {
        "component": "service",
        "label": "Microservices"
      },
      {
        "component": "apache-kafka",
        "label": "Message Broker"
      }
    ],
    "takeaway": {
      "title": "Atomicity and Reliability",
      "body": "The Outbox Pattern ensures atomic updates to databases and event publishing by storing events in an outbox table before publishing to a message broker, guaranteeing that either both the database update and event publication occur, or neither does."
    }
  }
}
